    [{"question": "Why should a revision plan prioritize certain topics?", "options": ["Some topics carry more exam weight and need more time", "All topics should get equal time regardless", "AI decides what's important", "Prioritizing means skipping topics"], "correct_index": 0, "explanation": "If the exam is 60% practical, SQL and design deserve more revision time than purely theoretical topics."}, {"question": "What makes a revision plan better than just 'studying everything'?", "options": ["Structure, time management, and targeted practice", "It's longer and more detailed", "It eliminates the need to study", "It guarantees good grades"], "correct_index": 0, "explanation": "A structured plan helps you allocate time effectively, identify weak areas, and include active practice."}],
    {"pass": "Excellent plan! Your instruction balances theory and practice.", "partial": "Good start. Consider adding specific practice activities for each day.", "fail": "Try again. Think about: how many days, hours per day, and which topics need more time."},
